INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 2, 'theory', 'Quiz: filtering with WHERE');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 2, 0, 'How does the condition a = 1 OR b = 2 AND c = 3 work?', '["Left to right: OR first, then AND", "As a = 1 OR (b = 2 AND c = 3): AND binds tighter", "As (a = 1 OR b = 2) AND c = 3", "It gives a syntax error"]', 1, 'AND has higher precedence than OR. To get a different grouping, you need parentheses.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 2, 1, 'Which values does the condition price BETWEEN 1000 AND 5000 return?', '["Strictly between 1000 and 5000, bounds not included", "From 1000 inclusive up to 5000 exclusive", "From 1000 to 5000, bounds included", "Only values equal to 1000 or 5000"]', 2, 'BETWEEN is equivalent to price >= 1000 AND price <= 5000: both bounds are part of the range.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 2, 2, 'What will the pattern LIKE `''_ов%''` find?', '["Strings containing «ов» anywhere", "Strings where the second and third letters are «ов»", "Strings exactly three characters long", "Strings ending in «ов»"]', 1, 'The underscore stands for exactly one character, and % for any sequence (including an empty one). The pattern requires any first character, then «ов», and anything after it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 2, 3, 'Why does the query SELECT price * 2 AS p2 FROM products WHERE p2 > 100 end with an error?', '["The alias cannot be named p2", "WHERE runs before SELECT, and the alias does not exist yet", "Multiplication cannot be used in SELECT", "You need to write HAVING instead of WHERE"]', 1, 'The order is FROM → WHERE → SELECT. At the WHERE stage the alias has not been computed yet; write the condition with the expression price * 2 > 100.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 2, 4, 'How do you correctly compare an order date with the first of May 2024 in SQLite?', '["created > ''2024-05-01''", "created > 01.05.2024", "created > DATE(1.5.2024)", "created > 2024/5/1"]', 0, 'Dates are stored as YYYY-MM-DD strings: alphabetical order matches chronological order, so they can be compared like ordinary strings.');
